import json, subprocess, warnings, os
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "पैर के अंगूठे में अचानक तेज़ दर्द? सूजन और लाली, अक्सर रात में? यह यूरिक एसिड बढ़ने का संकेत हो सकता है. आज शनिवार की हेल्थ टिप में जानिए, यूरिक एसिड टेस्ट. आखिर तक देखिए.",
 "यूरिक एसिड शरीर का एक वेस्ट है. यह प्यूरीन नाम की चीज़ के टूटने से बनता है. प्यूरीन हमारी कोशिकाओं में, और कुछ खाने की चीज़ों में होता है. ज़्यादातर यूरिक एसिड किडनी से, पेशाब के रास्ते बाहर निकल जाता है.",
 "जब शरीर ज़्यादा यूरिक एसिड बनाता है, या किडनी उसे कम निकाल पाती है, तो खून में इसका लेवल बढ़ जाता है. तब जोड़ों में सुई जैसे बारीक क्रिस्टल जम सकते हैं. इसी से गाउट का दर्द होता है. कुछ लोगों में किडनी की पथरी भी बन सकती है.",
 "यूरिक एसिड किन चीज़ों से बढ़ सकता है? रेड मीट और कलेजी. कुछ सी फूड. शराब, खासकर बियर. मीठे कोल्ड ड्रिंक. ज़्यादा वज़न, किडनी की बीमारी, और कुछ दवाएं. परिवार में गाउट हो, तो भी खतरा बढ़ता है.",
 "किसे यह टेस्ट करवाना चाहिए? जिनके जोड़ में अचानक दर्द और सूजन हो, खासकर पैर के अंगूठे में. जिन्हें किडनी की पथरी हो. जिनका गाउट का इलाज चल रहा हो. किडनी की बीमारी या कैंसर के इलाज में भी, डॉक्टर यह जांच करवाते हैं.",
 "यह एक साधारण ब्लड टेस्ट है. कुछ लैब कुछ घंटे खाली पेट आने को कहती हैं, इसलिए अपनी लैब का निर्देश मानें. टेस्ट से पहले शराब से बचें. जो दवाएं ले रहे हैं, उनके बारे में डॉक्टर को ज़रूर बताएं. पथरी में, कभी कभी चौबीस घंटे के पेशाब में भी यूरिक एसिड देखा जाता है.",
 "रिपोर्ट कैसे पढ़ें? आमतौर पर यूरिक एसिड लगभग साढ़े तीन से सात, एम जी पर डी एल के बीच रहता है. महिलाओं में यह थोड़ा कम होता है. रेंज लैब के हिसाब से बदलती है, इसलिए अपनी रिपोर्ट पर लिखी रेंज देखें. सिर्फ एक नंबर से बीमारी तय नहीं होती, डॉक्टर लक्षण के साथ देखते हैं.",
 "कुछ ज़रूरी बातें. गाउट के दर्द के समय, यूरिक एसिड कभी कभी नॉर्मल भी आ सकता है. बहुत से लोगों का यूरिक एसिड बढ़ा होता है, पर गाउट कभी नहीं होता. दवा चाहिए या नहीं, यह डॉक्टर तय करते हैं. और रिसर्च के अनुसार, दाल और पालक जैसी सब्ज़ियां, मीट, सी फूड और बियर की तरह गाउट का खतरा नहीं बढ़ातीं.",
 close_voice("क्या आपने कभी यूरिक एसिड टेस्ट करवाया है?"),
]
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/uar_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/ua_{i}.wav"],check=True); f=f"/tmp/ua_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/ua_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
